  max-width: 90vw;
  max-height: 80vh;
  overflow-y: auto;
  box-shadow: 0 25px 50px rgba(0,0,0,0.5);
}

.modal-title {
  font-size: 20px;
  font-weight: 700;
  margin-bottom: 20px;
}

.modal-actions {
  display: flex;
  gap: 8px;
  justify-content: flex-end;
  margin-top: 24px;
}

/* Plans/Upgrade */
.plans-container {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
}

.plan-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 16px;
  padding: 32px;
  text-align: center;
  transition: all 0.2s;
}

.plan-card:hover {
  border-color: var(--accent);
  transform: translateY(-2px);
}

.plan-card.premium {
  border-color: var(--gold);
  background: linear-gradient(135deg, rgba(245, 158, 11, 0.05), rgba(245, 158, 11, 0.1));
}

.plan-name {
  font-size: 20px;
  font-weight: 700;
  margin-bottom: 4px;
}

.plan-price {
  font-size: 14px;
  color: var(--text-secondary);
  margin-bottom: 20px;
}

.plan-features {
  list-style: none;
  text-align: left;
  margin-bottom: 24px;
}

.plan-features li {
  padding: 8px 0;
  font-size: 14px;
  color: var(--text-primary);
  display: flex;
  align-items: center;
  gap: 8px;
}

.plan-features li::before {
  content: '✓';
  color: var(--success);
  font-weight: 700;
}

/* Danger Zone */
.danger-zone {
  border: 1px solid var(--danger);
  border-radius: 12px;
  padding: 20px;
  background: rgba(239, 68, 68, 0.05);
}

.danger-zone-title {
  font-size: 16px;
  font-weight: 600;
  color: var(--danger);
  margin-bottom: 12px;
}

/* Animations */
@keyframes spin {
  to { transform: rotate(360deg); }
}

.spinner {
  width: 20px;
  height: 20px;
  border: 2px solid var(--border);
  border-top-color: var(--accent);
  border-radius: 50%;
  animation: spin 0.6s linear infinite;
}

.empty-state {
  text-align: center;
  padding: 60px 20px;
  color: var(--text-secondary);
}

.empty-state-icon {
  font-size: 48px;
  margin-bottom: 16px;
  opacity: 0.5;
}

.empty-state-text {
  font-size: 16px;
  margin-bottom: 8px;
}

.empty-state-sub {
  font-size: 13px;
}

/* Tabs */
.tabs {
  display: flex;
  gap: 0;
  margin-bottom: 20px;
  background: var(--bg-input);
  border-radius: 10px;
  padding: 4px;
}

.tab {
  padding: 8px 20px;
  border: none;
  background: transparent;
  color: var(--text-secondary);
  cursor: pointer;
  border-radius: 8px;
  font-size: 13px;
  font-weight: 500;
  transition: all 0.15s;
}

.tab.active {
  background: var(--accent);
  color: white;
}

/* Premium crown */
.crown {
  color: var(--gold);
  font-size: 16px;
}

.crown-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  background: linear-gradient(135deg, rgba(245,158,11,0.2), rgba(245,158,11,0.1));
  color: var(--gold);
  padding: 2px 8px;
  border-radius: 4px;
  font-size: 11px;
  font-weight: 600;
}

/* Theme preview */
.theme-option {
  padding: 12px;
  border-radius: 8px;
  border: 2px solid var(--border);
  cursor: pointer;
  transition: all 0.15s;
  text-align: center;
}

.theme-option:hover {
  border-color: var(--accent);
}

.theme-option.selected {
  border-color: var(--accent);
  background: rgba(79, 70, 229, 0.1);
}

.theme-preview {
  width: 100%;
  height: 60px;
  border-radius: 6px;
  margin-bottom: 8px;
}

/* Notifications */
.toast {
  position: fixed;
  bottom: 24px;
  right: 24px;
  padding: 12px 20px;
  border-radius: 10px;
  color: white;
  font-size: 14px;
  font-weight: 500;
  z-index: 2000;
  animation: slideIn 0.3s ease;
  box-shadow: 0 8px 30px rgba(0,0,0,0.3);
}

.toast-success { background: var(--success); }
.toast-error { background: var(--danger); }
.toast-info { background: var(--accent); }

@keyframes slideIn {
  from { transform: translateX(100%); opacity: 0; }
  to { transform: translateX(0); opacity: 1; }
}
